Hi Deborah here is a modified version of the function that can optionally accept values for score, status, xml (results) and delay (in seconds) for the form submission. To submit the form with the default values, try either of these: getURL("javascript:submitForm()") getURL("javascript:submitForm(100, 4, '', 0)"); Or to submit a score of 79% with a delay of 2 seconds, try this: getURL("javascript:submitForm(79, 4, '', 2)"); Or if the score and delay are stored in varlables, "myScore" and "myDelay" in your ActionScript, you can pass those like this: getURL("javascript:submitForm(" + myScore + ", 4, '', " + myDelay + ")"); Hopefully that should give you a few ideas to experiment with all the best ! Gordon 
```text
<script type="text/javascript">
//<![CDATA[
function submitForm(score, status, xml, delay) {
    // score  : 0 .. 100
    // status : status of quiz attempt
    //          1=in progress, 2=timedout, 3=abandoned, 4=completed
    // xml    : details of quiz attempt, encoded as 
XML

    // delay  : time delay (in seconds) before results are sent

    // locate submission form
    var obj = document.getElementById('store');
    if (obj) {

        // set default values
        if (typeof(score)=='undefined') {
            score = 100;
        }
        if (typeof(status)=='undefined') {
            status = 4;
        }
        if (typeof(xml)=='undefined') {
            xml = '';
        }
        if (typeof(delay)=='undefined') {
            delay = 0;
        }

        // insert values into form
        obj.score.value = score;
        obj.status.value = status;
        obj.detail.value = xml;

        // submit form (after delay, if required)
        if (delay) {
            setTimeout("document.getElementById('store').submit();", delay * 1000);
        } else {
            obj.submit();
        }
    }
}
//]]>
</script>
```

