Hi Eakchai, Stan's right, as a general rule you shouldn't force people to open new windows because it might not suit their situation or preference. I also would like to discourage you from messing with the standard Moodle php files, because although it will fix your immediate problem, you may well find later that you can't upgrade Moodle, because if you do you may lose your modifications. However, maybe you feel strongly that you are the teacher and you have decided that you want your students to open activities in a new window. OK, here's one way to do it. on your Moodle profile page, switch OFF the HTML editor on your course page, switch on "Edit mode" click the edit button in the top section of your course copy and paste the following code into the top of the content text box 
```text
<script type="text/
javascript
">
//<![CDATA[

function new_window_links() {

    var m = navigator.userAgent.match(new RegExp('MSIE (\\d+)'));
    if (m && m[1]<=7) {
        // IE7 and earlier
        var classAttribute = 'className';
    } else {
        var classAttribute = 'class';
    }

    var activities = document.getElementsByTagName('li');
    if (activities) {
        var i_max = activities.length;
    } else {
        var i_max = 0;
    }

    for (var i=0; i<i_max; i++) {

        if (typeof(activities[i].id)!='string' || activities[i].id.substr(0, 7)!='module-') {
            continue; // not an item in a list of activities
        }

        var myClassName = activities[i].getAttribute(classAttribute);
        if (typeof(myClassName)!='string' || myClassName.substr(0, 8)!='activity') {
            continue; // not an Moodle activity
        }

        var links = activities[i].getElementsByTagName('a');
        if (links) {
            var ii_max = links.length;
        } else {
            var ii_max = 0;
        }

        for (var ii=ii_max-1; ii>=0; ii--) {
            if (typeof(links[ii].href)=='string') {
                var m = links[ii].href.match(new RegExp('mod/[a-z0-9]+/view\\.php\\?id=([0-9]+)'))
                if (m && m[1]) {
                    links[ii].target = '_blank';
                }
            }
        }
    }
    return true;
}

if (window.addEventListener){
	window.addEventListener('load', new_window_links, false);
} else if (window.attachEvent){
	window.attachEvent('onload', new_window_links);
} else {
	window.onload = new_window_links;
}

//]]>
</script>
```
 save the changes All the links to activities in the central column should now open in a new window/tab enjoy! Gordon

